function startGame(saved){resetMotion();guard=0;deathTimer=0;hitFlash=0;autoPotionCD=0;actor.rotation.z=0;keys.clear();releaseStick();for(const p of projectiles){scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();}projectiles.length=0;player=saved||defaultPlayer(selectedClass);selectedClass=player.cls;questStage=player.quest||0;actor.position.set(player.x||0,0,Number.isFinite(player.z)?player.z:16);previousPosition.copy(actor.position);started=true;paused=false;$('#startScreen').hidden=true;clearWorldActors();spawnEnemies();if(saved?.worldState)restoreWorld(saved.worldState);updateClass();auto=false;skillsCD.fill(0);toast('서약이 시작되었습니다. 목표를 따라 폐허로 향하세요.');updateUI();save();}
