function spawnEnemy(x,z,type=0,boss=false){const hp=(boss?620:38+type*14)*(1+(player.level-1)*.08);let root=enemyVisual(type,boss);root.position.set(x,0,z);scene.add(root);let e={root,x,z,home:{x,z},hp,maxHP:hp,type,boss,cd:rand(.3,1.5),dead:false,slow:0,flash:0,windup:0,telegraph:null,phase:0,gait:0,motionBlend:0,prevX:x,prevZ:z};enemies.push(e);return e;}
