function sound(freq=300,duration=.08,type='triangle',gain=.04){if(!sound.enabled)return;try{sound.ctx||=(new(window.AudioContext||window.webkitAudioContext)());const c=sound.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,c.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.45,c.currentTime+duration);g.gain.setValueAtTime(gain,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+duration);}catch{}}
