function floatText(text,pos,kind=''){const p=new THREE.Vector3(pos.x,1.9,pos.z).project(camera);if(Math.abs(p.x)>1.2||Math.abs(p.y)>1.2)return;const d=document.createElement('div');d.className='float '+kind;d.textContent=text;d.style.left=(p.x*.5+.5)*innerWidth+'px';d.style.top=(-p.y*.5+.5)*innerHeight+'px';$('#combatText').append(d);setTimeout(()=>d.remove(),1050);}
