function damageEnemy(e,n,slow=0){if(e.dead)return;let critical=Math.random()<stats().crit;n=Math.round(n*(critical?1.65:1));e.hp-=n;e.flash=.17;e.slow=Math.max(e.slow,slow);floatText((critical?'✦ ':'')+n,e,critical?'gold':'');sparkle(e.x,e.z,CLASSES[player.cls].color);if(e.hp<=0)killEnemy(e);}
function killEnemy(e){e.dead=true;e.root.rotation.z=Math.PI/2;if(e.telegraph){scene.remove(e.telegraph);e.telegraph=null;}e.root.position.y=.08;e.root.scale.multiplyScalar(.8);player.kills++;let xp=e.boss?180:17+e.type*4;player.xp+=xp;player.gold+=e.boss?80:Math.floor(rand(4,11));if(e.boss){player.bossKills++;questStage=2;player.quest=2;eliteKilled=true;toast('파수꾼을 쓰러뜨렸습니다. 전리품을 챙겨 쉼터로 돌아가세요.');showBanner('서약의 불씨를 되찾았습니다');dropLoot(e.x,e.z,true);dropLoot(e.x+1,e.z,true);}else if(Math.random()<.75)dropLoot(e.x,e.z);if(Math.random()<.18)player.potions=Math.min(15,player.potions+1);if(questStage===0&&player.kills>=6){questStage=1;player.quest=1;toast('성소로 향하는 길이 열렸습니다. 북쪽 파수꾼을 찾으세요.');}while(player.xp>=xpNeed()){player.xp-=xpNeed();player.level++;player.points+=3;player.hp=stats().maxHP;player.mp=stats().maxMP;effect(actor.position.x,actor.position.z,3,0xffdf83,.8);toast('레벨 '+player.level+' · 능력치 포인트 3개를 직접 배분할 수 있습니다.');sound(700,.3);}save();}
function xpNeed(){return 55+player.level*25;}
function generateItem(boss=false){let slot=pick(Object.keys(SLOTS)),r=Math.random(),rarity=boss?(r<.22?3:2):(r<.04?2:r<.38?1:0),level=player.level;let item={id:crypto.randomUUID?.()||String(Date.now()+Math.random()),slot,rarity,level,name:ITEM_NAMES[slot][rarity],attack:0,defense:0,hp:0,crit:0};let power=(2+level)*(1+rarity*.8);if(slot==='weapon')item.attack=Math.round(power*1.7);if(slot==='armor')item.defense=Math.round(power*.9);if(slot==='ring')item.hp=Math.round(power*4);if(rarity>0)item.crit=(rarity+1)*.015;if(rarity>=2){item.hp+=10+level*3;item.attack+=2+level;}return item;}
function dropLoot(x,z,boss=false){const item=generateItem(boss),color=[0xb8bcba,0x70abf0,0xe3c25a,0xe69847][item.rarity],g=new THREE.Group();box(.3,.13,.5,new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.6}),0,.15,0,g);const beam=mesh(new THREE.CylinderGeometry(.025,.08,1.4,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.36,depthWrite:false}),0,.8,0,g);g.position.set(x,0,z);scene.add(g);drops.push({x,z,item,mesh:g,beam});}
function pickup(){if(!started||paused)return;const near=drops.filter(d=>dist(actor.position,d)<2.1);if(!near.length)return;if(player.items.length>=24){auto=false;toast('가방이 가득 찼습니다. 장비에서 정리하세요.');return;}for(const d of near){if(player.items.length>=24)break;player.items.push(d.item);scene.remove(d.mesh);drops.splice(drops.indexOf(d),1);floatText(d.item.name,d,'gold');sound(640,.1);}save();updateUI();}
function nearest(range=100){let best=null,bd=range;for(const e of enemies){if(e.dead||e.boss&&questStage===0)continue;let d=dist(actor.position,e);if(d<bd){best=e;bd=d;}}return best;}
