function updateUI(){if(!player)return;const s=stats();$('#level').textContent='Lv.'+player.level;$('#hpFill').style.width=clamp(player.hp/s.maxHP*100,0,100)+'%';$('#mpFill').style.width=clamp(player.mp/s.maxMP*100,0,100)+'%';$('#hpText').textContent=Math.ceil(player.hp)+' / '+s.maxHP;$('#mpText').textContent=Math.floor(player.mp)+' / '+s.maxMP;$('#xpFill').style.width=player.xp/xpNeed()*100+'%';$('#gold').textContent=player.gold;$('#potions').textContent=player.potions;$('#autoButton').textContent=auto?'자동 사냥 켜짐 · V':'자동 사냥 꺼짐 · V';$('#autoButton').classList.toggle('active',auto);$('#stateLabel').textContent=paused?'일시 정지':auto?'자동 · 개입하면 수동 전환':guard>0?'방벽 유지 중':'수동 · 이동 / 공격';const titles=['재의 성문을 열어라','무너진 서약의 파수꾼','불씨를 쉼터로','첫 번째 서약 완료'];$('#questTitle').textContent=titles[questStage]||titles[3];$('#questText').textContent=questStage===0?`폐허의 망령 ${Math.min(6,player.kills)} / 6 처치`:questStage===1?'북쪽 성소의 파수꾼을 처치하세요.':questStage===2?'전리품을 줍고 쉼터로 귀환하세요.':'장비를 바꾸고 새 원정을 시작할 수 있습니다.';$('#questTrack').textContent=questStage>=2?'쉼터 귀환':'목표로 자동 이동';for(const b of $$('[data-skill]')){let i=+b.dataset.skill,cd=skillsCD[i],max=[.65,5,9,8][i];b.querySelector('em').style.height=Math.min(100,cd/max*100)+'%';b.title=cd>0?cd.toFixed(1)+'초':'사용 가능';}}
function drawMap(){const c=$('#minimap').getContext('2d'),w=160,h=126; c.clearRect(0,0,w,h);c.fillStyle='#101c24';c.fillRect(0,0,w,h);const mx=x=>(x+24)/48*w,mz=z=>(z+32)/56*h;c.strokeStyle='#77735b';c.lineWidth=4;c.beginPath();c.moveTo(mx(0),mz(20));c.lineTo(mx(0),mz(-28));c.stroke();for(const o of obstacles){c.fillStyle='#59605a';c.fillRect(mx(o.x-o.w),mz(o.z-o.d),o.w*2/48*w,o.d*2/56*h);}c.strokeStyle='#d1b66e';c.beginPath();c.arc(mx(0),mz(12),11,0,6.28);c.stroke();for(const e of enemies){if(e.dead)continue;c.fillStyle=e.boss?'#f4b55c':'#c46b64';c.beginPath();c.arc(mx(e.x),mz(e.z),e.boss?4:2,0,6.28);c.fill();}for(const d of drops){c.fillStyle='#d8c16c';c.fillRect(mx(d.x)-1,mz(d.z)-1,2,2);}c.fillStyle='#b3eee2';c.beginPath();c.arc(mx(actor.position.x),mz(actor.position.z),3,0,6.28);c.fill();}
function save(){if(!player)return;try{player.x=actor.position.x;player.z=actor.position.z;player.quest=questStage;player.worldState={enemies:enemies.map(e=>({hp:Math.max(0,e.hp),dead:e.dead,x:e.x,z:e.z,type:e.type,boss:e.boss})),drops:drops.map(d=>({x:d.x,z:d.z,item:d.item}))};localStorage.setItem(SAVE,JSON.stringify(player));}catch(e){if(!saveError){saveError=true;toast('자동 저장 공간에 쓸 수 없습니다. 메뉴에서 백업 파일을 내려받으세요.');}}}
function validItem(i){return i&&Object.keys(SLOTS).includes(i.slot)&&Number.isInteger(i.rarity)&&i.rarity>=0&&i.rarity<=3&&Number.isInteger(i.level)&&i.level>=1&&i.level<=100&&typeof i.name==='string'&&i.name.length<=80&&typeof i.id==='string'&&i.id.length<=80&&['attack','defense','hp','crit'].every(k=>Number.isFinite(i[k])&&i[k]>=0&&i[k]<(k==='crit'?1:10000));}
function validWorld(w){return !w||(Array.isArray(w.enemies)&&w.enemies.length<50&&w.enemies.every(e=>Number.isFinite(e.hp)&&e.hp>=0&&e.hp<100000&&Number.isFinite(e.x)&&Math.abs(e.x)<50&&Number.isFinite(e.z)&&Math.abs(e.z)<50&&typeof e.dead==='boolean'&&typeof e.boss==='boolean'&&Number.isInteger(e.type)&&e.type>=0&&e.type<10)&&Array.isArray(w.drops)&&w.drops.length<100&&w.drops.every(d=>Number.isFinite(d.x)&&Math.abs(d.x)<50&&Number.isFinite(d.z)&&Math.abs(d.z)<50&&validItem(d.item)));}
function validSave(d){return d&&d.version===VERSION&&CLASSES[d.cls]&&Number.isInteger(d.level)&&d.level>=1&&d.level<101&&Number.isFinite(d.gold)&&d.gold>=0&&d.gold<1e9&&Array.isArray(d.items)&&d.items.length<=24&&d.items.every(validItem)&&d.equipment&&Object.keys(SLOTS).every(k=>d.equipment[k]===null||validItem(d.equipment[k]))&&d.spent&&['might','vitality','focus'].every(k=>Number.isInteger(d.spent[k])&&d.spent[k]>=0&&d.spent[k]<=300)&&['hp','mp','kills','xp','potions','points'].every(k=>Number.isFinite(d[k])&&d[k]>=0&&d[k]<1e7)&&Number.isFinite(d.x)&&Math.abs(d.x)<23&&Number.isFinite(d.z)&&Math.abs(d.z)<33&&Number.isInteger(d.quest)&&d.quest>=0&&d.quest<=3&&validWorld(d.worldState);}
function restoreWorld(w){if(!validWorld(w))return;for(let i=0;i<w.enemies.length;i++){const v=w.enemies[i];let e=enemies[i];if(!e)e=spawnEnemy(v.x,v.z,v.type,v.boss);e.hp=Math.min(v.hp,e.maxHP);e.dead=v.dead||e.hp<=0;e.x=v.x;e.z=v.z;e.root.position.set(e.x,0,e.z);if(e.dead){e.root.rotation.z=Math.PI/2;e.root.position.y=.08;e.root.scale.multiplyScalar(.8);}}for(const d of w.drops){const color=[0xb8bcba,0x70abf0,0xe3c25a,0xe69847][d.item.rarity],g=new THREE.Group();box(.3,.13,.5,new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.6}),0,.15,0,g);const beam=mesh(new THREE.CylinderGeometry(.025,.08,1.4,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.36,depthWrite:false}),0,.8,0,g);g.position.set(d.x,0,d.z);scene.add(g);drops.push({...d,mesh:g,beam});}}

function exportSave(){save();const blob=new Blob([JSON.stringify(player,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ashen-oath-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function openPanel(title,html){paused=true;queuedSkill=null;keys.clear();releaseStick();$('#panelTitle').textContent=title;$('#panelContent').innerHTML=html;$('#panelOverlay').hidden=false;updateUI();}
function closePanel(){$('#panelOverlay').hidden=true;paused=!started;updateUI();}
function itemDetail(i){return[i.attack?`공격 +${i.attack}`:'',i.defense?`방어 +${i.defense}`:'',i.hp?`체력 +${i.hp}`:'',i.crit?`치명 +${Math.round(i.crit*100)}%`:''].filter(Boolean).join(' · ');}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function openInventory(){if(!started)return;const s=stats();let equipment=Object.entries(SLOTS).map(([k,n])=>`<div class="equipSlot">${n}<b>${esc(player.equipment[k]?.name||'장착 없음')}</b><span>${player.equipment[k]?itemDetail(player.equipment[k]):''}</span></div>`).join('');openPanel('장비와 성장',`<div class="statsGrid"><div class="stat">공격력<b>${s.attack}</b></div><div class="stat">방어력<b>${s.defense}</b></div><div class="stat">최대 체력<b>${s.maxHP}</b></div><div class="stat">치명타<b>${Math.round(s.crit*100)}%</b></div><div class="stat">경험치<b>${player.xp} / ${xpNeed()}</b></div><div class="stat">성장 포인트<b>${player.points}</b></div></div><div class="toolbar"><button data-stat="might">힘 +3공격</button><button data-stat="vitality">생명 +12체력</button><button data-stat="focus">집중 +8정신력</button></div><h3>현재 장착</h3><div class="equipment">${equipment}</div><div class="notice">직접 비교하고 장착하세요. 자동 장착·판매·분해는 하지 않습니다. 메뉴가 열려 있는 동안 전투는 멈춥니다.</div><h3>가방 ${player.items.length} / 24</h3><div class="inventory">${player.items.map((i,k)=>`<button class="item ${['','magic','rare','unique'][i.rarity]}" data-item="${k}"><b>${esc(i.name)}</b><span>${RARITIES[i.rarity]} · ${SLOTS[i.slot]} · Lv.${i.level}</span><span>${itemDetail(i)}</span></button>`).join('')||'<p>주운 장비가 없습니다.</p>'}</div><div class="toolbar"><button id="restock">물약 3개 구입 · 30골드</button><button id="newRun">새 원정 · 적 재생성</button><button id="backup">저장 백업</button><button id="import">백업 가져오기</button></div><p class="fine">게임 안 골드만 사용합니다. 실제 결제는 없습니다. 저장은 현재 브라우저·기기에만 남습니다.</p>`);$$('[data-stat]').forEach(b=>{b.disabled=player.points<1;b.onclick=()=>{player.spent[b.dataset.stat]++;player.points--;save();openInventory();};});$$('[data-item]').forEach(b=>b.onclick=()=>showItem(+b.dataset.item));$('#backup').onclick=exportSave;$('#import').onclick=()=>$('#importFile').click();$('#restock').onclick=()=>{if(player.gold<30)return toast('게임 골드가 30 필요합니다.');player.gold-=30;player.potions=Math.min(15,player.potions+3);save();toast('물약 3개를 받았습니다.');openInventory();};$('#newRun').onclick=()=>{if(actor.position.z<6)return toast('쉼터로 돌아온 뒤 원정을 시작하세요.');resetMotion();guard=0;deathTimer=0;skillsCD.fill(0);clearWorldActors();player.kills=0;questStage=0;player.quest=0;player.hp=stats().maxHP;player.mp=stats().maxMP;spawnEnemies();save();closePanel();toast('새 원정이 준비되었습니다. 장비와 성장은 유지됩니다.');};}
function showItem(k){const i=player.items[k],eq=player.equipment[i.slot];openPanel(i.name,`<p>${RARITIES[i.rarity]} ${SLOTS[i.slot]} · 레벨 ${i.level}</p><h3>선택한 장비</h3><p>${itemDetail(i)}</p><h3>현재 장비와 비교</h3><p>${eq?esc(eq.name)+' · '+itemDetail(eq):'이 칸에 장착한 장비가 없습니다.'}</p><div class="toolbar"><button class="primary" id="equip">장착</button><button id="sell">이 장비 판매 · ${8+i.rarity*12+i.level*2}골드</button><button id="backBag">가방으로</button></div><p class="fine">장착하면 기존 장비는 가방으로 돌아옵니다.</p>`);$('#equip').onclick=()=>{player.items.splice(k,1);if(eq)player.items.push(eq);player.equipment[i.slot]=i;player.hp=Math.min(player.hp,stats().maxHP);save();openInventory();sound(400,.15);};$('#sell').onclick=()=>{openPanel('판매 확인',`<p>${esc(i.name)}을(를) 판매하면 되돌릴 수 없습니다.</p><div class="toolbar"><button id="confirmSell">${8+i.rarity*12+i.level*2}골드에 판매</button><button id="cancelSell">취소</button></div>`);$('#confirmSell').onclick=()=>{player.items.splice(k,1);player.gold+=8+i.rarity*12+i.level*2;save();openInventory();};$('#cancelSell').onclick=()=>showItem(k);};$('#backBag').onclick=openInventory;}
function showHelp(){openPanel('순례자의 안내',`<ul><li>PC: WASD / 방향키 이동. V는 자동 전투 전환.</li><li>Space 기본 공격, 1·2·3 기술, Q 물약, F 전리품 줍기, I 장비, T 쉼터 귀환.</li><li>모바일: 왼쪽 상대식 스틱과 하단 기술. 가로 화면을 권장합니다.</li><li>자동 전투는 길찾기·공격·물약·줍기를 지원합니다. 수동 이동/기술을 쓰면 자동이 꺼집니다.</li><li>붉은 공격 예고 범위에서 벗어나세요. 파수꾼은 망령 6마리를 처치한 뒤 도전할 수 있습니다.</li><li>장비·성장 선택은 직접 합니다. 장비 메뉴와 일시정지 중에는 전투가 멈춥니다.</li><li>쓰러지면 시험용 규칙: 소지 골드 2%(최대 100)를 잃고 쉼터로 귀환합니다. 장비·경험치는 잃지 않습니다. 이 수치는 최종 확정 전입니다.</li><li>자동 저장은 기기별입니다. 장비 메뉴에서 백업/가져오기를 사용할 수 있습니다.</li></ul><div class="toolbar"><button id="soundToggle">소리 ${sound.enabled?'끄기':'켜기'}</button><button id="licenses">출처와 라이선스</button></div><p class="fine">개발 확인판 v0.1.9. 아직 본편·소환술사·제작·룬·심층은 구현하지 않았습니다. 실제 아이폰 성능 검증은 별도입니다.</p>`);$('#soundToggle').onclick=()=>{sound.enabled=!sound.enabled;showHelp();};$('#licenses').onclick=showCredits;}
function showCredits(){openPanel('출처와 라이선스',`<p>잿빛 서약은 독자적인 세계·이야기·게임 규칙으로 만드는 액션 RPG입니다. Diablo 및 Blizzard와 관련이 없습니다. 원작의 이미지·로고·음원·지도·대사를 사용하지 않습니다.</p><ul><li>플레이어 모델: SamuraiThirdPersonTemplateThreeJS의 공통 Samurai 몸체를 변환·텍스처 축소하고 자체 동작·직업 색상을 적용했습니다. <a target="_blank" rel="noopener" href="https://github.com/achrefelouafi/SamuraiThirdPersonTemplateThreeJS">템플릿</a> (코드 MIT).</li><li>원 모델 후보: <a target="_blank" rel="noopener" href="https://sketchfab.com/3d-models/shadowflame-samurai-03def921ed814b3a9de5c5962b86a45c">Shadowflame Samurai</a>, dark_igorek, Sketchfab CC BY 4.0. 포함 파일과 원본 대응 확인 중. 변환·해상도·재질·자체 동작 변경.</li><li>Mixamo 애니메이션 파일은 포함하지 않습니다. 동작은 런타임에서 직접 계산합니다.</li><li>렌더링: Three.js (MIT). 배경·적·이펙트·음향은 이 프로젝트에서 코드로 생성했습니다.</li></ul><p class="fine">세부 출처·권리 고지는 저장소의 THIRD_PARTY_NOTICES.md를 참고하세요.</p>`);}
$$('[data-class]').forEach(b=>b.onclick=()=>{selectedClass=b.dataset.class;$$('[data-class]').forEach(x=>x.classList.toggle('selected',x===b));});$('#startButton').onclick=()=>{sound(440);startGame();};$('#continueButton').onclick=()=>{try{const d=JSON.parse(localStorage.getItem(SAVE));if(validSave(d))startGame(d);else toast('저장 데이터 형식이 맞지 않습니다. 백업을 확인하세요.');}catch{toast('저장 데이터를 읽지 못했습니다.');}};$('#creditsButton').onclick=showCredits;$('#closePanel').onclick=closePanel;$('#gearButton').onclick=openInventory;$('#helpButton').onclick=showHelp;$('#pauseButton').onclick=()=>{if(!started)return;if(paused)closePanel();else openPanel('일시 정지','<p>서약은 잠시 기다립니다. 닫기를 누르면 계속합니다.</p>');};$('#autoButton').onclick=toggleAuto;$('#townButton').onclick=()=>{if(started&&!paused)returnTown();};$('#potionButton').onclick=potion;$('#lootButton').onclick=pickup;$('#questTrack').onclick=()=>{if(questStage>=2)returnTown();else if(!auto)toggleAuto();};$$('[data-skill]').forEach(b=>b.onpointerdown=e=>{e.preventDefault();manual();useSkill(+b.dataset.skill);});$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error();const d=JSON.parse(await f.text());if(!validSave(d))throw Error();openPanel('저장 복원 확인','<p>가져온 저장으로 현재 기기 진행을 바꿉니다. 먼저 현재 저장을 백업하는 것을 권장합니다.</p><div class="toolbar"><button id="doImport">복원</button><button id="cancelImport">취소</button></div>');$('#doImport').onclick=()=>{closePanel();startGame(d);toast('백업에서 서약을 복원했습니다.');};$('#cancelImport').onclick=openInventory;}catch{toast('올바른 잿빛 서약 v1 백업 파일이 아닙니다.');}e.target.value='';};
addEventListener('beforeunload',save);addEventListener('visibilitychange',()=>{if(document.hidden&&started){keys.clear();releaseStick();save();paused=true;openPanel('일시 정지','<p>다른 화면으로 이동해 전투를 멈췄습니다. 닫으면 이어집니다.</p>');}});
function resize(){renderer.setSize(innerWidth,innerHeight,false);const a=innerWidth/innerHeight,h=a<.8?13:a<1.4?11:9;camera.left=-h*a;camera.right=h*a;camera.top=h;camera.bottom=-h;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();
let last=performance.now();function frame(now){let dt=Math.min(.1,(now-last)/1000);last=now;frameCount++;if(now-lastFps>1000){fps=1/Math.max(.001,(now-frame.lastNow)/1000);lastFps=now;}update(dt);const target=started?actor.position:new THREE.Vector3(0,0,11);look.lerp(new THREE.Vector3(target.x,0,target.z),1-Math.exp(-dt*8));camera.position.set(look.x+13,22,look.z+16);camera.lookAt(look.x,0,look.z);sun.position.set(look.x-12,28,look.z+8);sun.target.position.copy(look);if(!sun.target.parent)scene.add(sun.target);if(groundMarker)groundMarker.position.set(actor.position.x,.045,actor.position.z);if(frameCount%8===0)drawMap();renderer.render(scene,camera);frame.lastNow=now;requestAnimationFrame(frame);}frame.lastNow=performance.now();requestAnimationFrame(frame);
