Object.defineProperty(window,'ashenOath',{get:()=>({version:'0.1.9-motion',started,paused,auto,fps,modelLoaded:!!model,position:{x:actor.position.x,z:actor.position.z},player:player?JSON.parse(JSON.stringify(player)):null,enemies:enemies.map(e=>({hp:e.hp,maxHP:e.maxHP,x:e.x,z:e.z,boss:e.boss,dead:e.dead})),drops:drops.length,renderer:{calls:renderer.info.render.calls,triangles:renderer.info.render.triangles},questStage})});
